INSERT INTO public.board (id, slug, name_en, name_zh, desc_en, desc_zh, icon, sort_order) VALUES (1, 'campus-life', 'Campus life', '校园生活', 'Day-to-day life on and around campus.', '校园内外的日常。', '🏫', 0);
INSERT INTO public.board (id, slug, name_en, name_zh, desc_en, desc_zh, icon, sort_order) VALUES (2, 'housing', 'Housing & dorms', '住宿', 'Dorms, renting off campus, roommates, moving.', '宿舍、校外租房、室友、搬家。', '🏠', 1);
INSERT INTO public.board (id, slug, name_en, name_zh, desc_en, desc_zh, icon, sort_order) VALUES (3, 'paperwork', 'Visas & paperwork', '签证与手续', 'Residence permits, registration, banking, phones. Always confirm with the official office.', '居留许可、登记、银行、手机卡。请务必以官方部门信息为准。', '🛂', 2);
