INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('30494876-3b49-4ac7-9ce7-2899bb300664', 2, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'question', 'Moving off campus next semester — what should I check before signing?', 'First time renting in China. Landlord seems nice but the contract is only in Chinese. What do people usually check, and is there somewhere I can get the contract looked at?', 'haining', NULL, 27, 4, '2026-10-01 05:49:46.976+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('ec53c8d5-e92c-481c-9665-cc690db36625', 3, '97024d98-d168-430c-b8f2-e676102d3cb5', 'question', 'Residence permit renewal — how early did you start?', 'Mine expires at the end of next month. The checklist I got in orientation is two years old and I am not sure it is still current.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', 5, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'tip', 'Best cheap lunch within 10 minutes of Zijingang?', 'Starting a thread so new students have one place to look. Under ¥30, walkable, go.', 'zijingang', NULL, 61, 5, '2026-09-30 18:49:46.973+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('f3604c91-3564-4563-9464-c82a431ac76f', 4, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'discussion', 'Study group for Linear Algebra final — anyone?', 'Thinking twice a week in the library, working through past problem sets together. English or Chinese both fine.', NULL, NULL, 38, 5, '2026-09-30 08:49:46.978+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('5c40edfb-d319-4a6b-9873-e9947ff1529b', 7, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'discussion', '中英语言交换 · 找一位英语母语的语伴', '我是玉泉校区的研二学生，想练口语。可以帮你练中文（普通话），每周一到两次，校内咖啡店见面。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('9f0f871f-c608-4277-8076-8159e9d8199c', 1, '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'tip', 'Things I wish I knew in my first month at ZJU', '1. Get a local phone number early, a lot of apps need it.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('3f4fe3cd-49f8-405b-92bc-dcd35d65ab41', 15, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'event', 'Saturday badminton — 4 more players needed', 'We have two courts booked this Saturday afternoon at the Zijingang sports centre. All levels welcome, bring your own racket if you have one.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('300efb8f-c5bf-4e98-a016-8d11d9a924a1', 15, '97024d98-d168-430c-b8f2-e676102d3cb5', 'discussion', 'Ping pong before class — looking for a regular partner', 'The tables in the Yuquan gym building are usually free before 9am. I am somewhere between beginner and bad, so there is no level to live up to here.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d9e0e517-9ba9-4459-8d62-2730c3997d83', 15, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'event', 'Sunday football at Zijingang — mixed levels, always short a keeper', 'We play most Sundays at 4pm. Usually a mix of international and Chinese students, usually about twelve of us, almost always missing a goalkeeper.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('42580320-8118-4e98-8f3d-ceeef805e0de', 16, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'question', 'Which clubs actually take international students?', 'Not which ones say they are open — which ones did you join and feel welcome in? My Chinese is still basic and I would rather hear it from someone who has done it.', NULL, NULL, 37, 4, '2026-09-29 22:49:46.987+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('ac666426-ff67-4939-a9e8-f46f783e6f7e', 16, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'event', 'Photography society open session on Thursday — no camera needed', 'Thursday evening is an open session, so you can come without joining anything. A phone is fine; half the people bring nothing at all and just walk with us.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('cb5c8f3e-7e8e-4b4c-b4e3-598b2ad2a662', 16, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'discussion', '街舞社招新，欢迎留学生同学', '每周三、周日晚上在玉泉体育馆排练，零基础也可以来，前两次是免费体验。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('707d30f9-9afc-4283-aa0b-2cbde025a11d', 6, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'event', 'International potluck next Friday — one dish from home each', 'Someone organised this last year and it was the best evening of the semester. One dish each, and write what is in it on a card beside it so people know what they are eating.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('bb09df51-03ae-4123-828b-82232498262a', 8, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'question', 'Part-time work or internships as an international student — what is allowed?', 'I have heard different things from different people. Some say internships are fine with approval, some say not at all. Has anyone actually gone through the process?', NULL, NULL, 29, 3, '2026-09-28 16:49:46.991+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('f1d4be20-3475-4dbc-82c1-c8b6f5fb95cb', 2, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'tip', 'Setting up a dorm room on a budget', 'Most of what you need is already on the Marketplace from students who are moving out. I got a desk, lamp and bedding for under ¥300 total.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('a69a555d-a011-412f-8e2d-df0b785e1894', 4, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'question', '有没有同学选过「国际商法」？考试难吗？', '下学期想选这门课，想了解一下考核方式和课程压力。英文授课的班级有什么需要注意的吗？', 'zhijiang', NULL, 16, 2, '2026-09-29 10:49:46.992+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('8f4fd0fd-e31f-491c-9f9b-7893478cc15a', 5, '97024d98-d168-430c-b8f2-e676102d3cb5', 'discussion', 'West Lake on a weekday morning is a completely different place', 'Went at 7am on a Wednesday. Almost empty, mist on the water, locals doing tai chi. If you have only been on a weekend you have not really seen it.', NULL, NULL, 52, 3, '2026-09-27 14:49:46.993+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('c5b3231b-9ee6-499e-adb2-554dc91466f6', 1, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'question', 'Is there a quiet place to study late at night?', 'The main library closes before I am done most days. Where do people go?', 'zijingang', NULL, 11, 2, '2026-10-01 02:49:46.994+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('85418831-7ca8-4f43-88dd-80f7df8f429b', 3, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'tip', 'Opening a bank account — what made it easier for me', 'Took me two tries. What worked the second time: going on a weekday morning, bringing passport + residence permit + student card + a local phone number, and having a Chinese-speaking friend come along.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('727ae2ac-18c3-4ba7-b597-5d1f1f398f28', 6, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'event', '周末去杭州植物园拍照，有人一起吗？', '周六上午出发，地铁过去，大概半天。欢迎带相机或者手机都行，主要是散步和拍照。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d0fb2686-501d-4c51-ba78-a03da19152bf', 4, '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'tip', 'Free tools that got me through my first semester of courses in Chinese', 'A pop-up dictionary browser extension for course websites, a flashcard app for the technical vocabulary of each course, and asking one Chinese classmate per course if I could compare notes after lectures.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('c2469263-57fa-4c51-9ead-8bb0636a17ae', 7, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'question', 'Looking for a Mandarin speaking partner — Arabic or English in return', 'HSK 4, want to get better at everyday conversation, not exam Chinese. Happy to teach Arabic or practise English.', 'zijingang', NULL, 13, 1, '2026-09-29 22:49:46.996+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('2163ef77-3b88-479a-92cc-a22e1e757c3a', 8, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'discussion', 'CV format for Chinese companies vs European ones', 'Noticed Chinese job postings often expect a photo and more personal details on the CV, which is the opposite of what I was taught at home. How do people handle this?', NULL, NULL, 21, 2, '2026-09-23 06:49:46.996+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('99c8fb76-07cd-4bee-b403-0874c750e0da', 2, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'question', '之江校区附近有推荐的短租吗？', '暑假有一个月需要留在杭州，宿舍不能住，想找一个短租的地方。', 'zhijiang', NULL, 8, 1, '2026-10-01 07:49:46.997+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('e41d13e0-2a47-42b6-9b26-41dddec1645a', 1, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'discussion', 'Haining campus appreciation post 🌿', 'Smaller than the Hangzhou campuses but honestly the most beautiful. The lake at sunset is unreal.', 'haining', NULL, 35, 3, '2026-09-28 06:49:46.997+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('651c69e5-74a3-45ca-8c76-0e07cdf9d1e6', 4, '97024d98-d168-430c-b8f2-e676102d3cb5', 'question', 'Where do people find past exam papers?', 'Some courses seem to have them floating around, some do not. Is there an official place?', NULL, NULL, 3, 0, '2026-10-01 12:49:46.998+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('14c11021-a497-4648-9486-240e2c6fc051', 6, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'event', 'Autumn welcome party — everyone is invited, nothing to pay', 'Friday from seven at the Student Centre. Music, food from a dozen countries, and a room full of people who also arrived this year.
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('db6f65d0-2004-4d0d-83bf-f4acf0fc5bc4', '9f0f871f-c608-4277-8076-8159e9d8199c', NULL, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Buy a proper winter coat before December, not after. I learned this the hard way.', 26, '2026-09-29 17:49:46.982+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('addd5a4f-ebd4-4de4-986b-53f8615f2da3', 'ec53c8d5-e92c-481c-9665-cc690db36625', NULL, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'I started about six weeks before. The International Student Office sends an email with the current checklist each semester, so I would go by that rather than the old one.', 18, '2026-10-01 10:49:46.969+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('4bd5b579-cecf-4dd1-b737-86dbb8f96a67', 'ec53c8d5-e92c-481c-9665-cc690db36625', 'addd5a4f-ebd4-4de4-986b-53f8615f2da3', '97024d98-d168-430c-b8f2-e676102d3cb5', 'Found it in my university inbox, thanks. It had changed.', 6, '2026-10-01 11:49:46.971+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('cfcb7de1-43ab-490d-8ccb-e928cadfa90a', 'ec53c8d5-e92c-481c-9665-cc690db36625', NULL, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'Bring more passport photos than you think you need. I had to go back once.', 11, '2026-10-01 12:49:46.971+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('a1800c1a-484d-4eb7-945d-7f30ac4f8a7f', 'ec53c8d5-e92c-481c-9665-cc690db36625', 'cfcb7de1-43ab-490d-8ccb-e928cadfa90a', '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'Same. Also make copies of every passport page with a stamp.', 3, '2026-10-01 13:49:46.972+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('939ffcf4-30ec-4f4b-9f34-19a87fdd38f5', 'ec53c8d5-e92c-481c-9665-cc690db36625', NULL, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'Book the appointment as soon as the slots open, they fill up near the end of the semester.', 4, '2026-10-01 13:49:46.972+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('add39c9c-023a-4c0c-a80d-d28372c877a6', 'd79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', NULL, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'The noodle place by the north gate. Ask for less chilli if you are new to it, "shao la" works.', 22, '2026-09-30 19:49:46.975+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('47a5d99a-74ca-4993-8c37-d92f425f625d', 'd79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', 'add39c9c-023a-4c0c-a80d-d28372c877a6', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Can confirm, and they have a picture menu.', 9, '2026-09-30 20:49:46.975+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d56e0e13-94ba-4958-8139-c0644871bb75', 'd79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', 'add39c9c-023a-4c0c-a80d-d28372c877a6', 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', '少辣 is the magic word 😄', 5, '2026-09-30 21:49:46.975+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('1aea7007-1dee-42d9-8c28-a91c00a7e076', 'd79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', NULL, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Canteen 2 upstairs does a decent set meal. Not exciting, very reliable.', 14, '2026-09-30 20:49:46.976+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d560597a-7d8a-4d80-8310-8985090b5a9c', 'd79b2b86-87c1-4dcc-b3a6-7cbb322bb4c6', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', '食堂的麻辣香锅性价比很高，中午人多建议早点去。', 7, '2026-09-30 23:49:46.976+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('106e67a8-ad3f-4a46-9aaa-068bdc174b00', '30494876-3b49-4ac7-9ce7-2899bb300664', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'Ask whether the landlord will help with the accommodation registration — you usually need to register your address after moving. Confirm the exact steps with the International Student Office.', 15, '2026-10-01 06:49:46.977+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('a8768589-95c4-49a7-a989-ad049707015e', '30494876-3b49-4ac7-9ce7-2899bb300664', '106e67a8-ad3f-4a46-9aaa-068bdc174b00', '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Did not know about that at all, thank you.', 4, '2026-10-01 07:49:46.977+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('0af827fa-0efe-4d17-a050-a8e37dda7d5e', '30494876-3b49-4ac7-9ce7-2899bb300664', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Photograph every room and every existing scratch before you move in, and send the photos to the landlord in WeChat so there is a timestamp.', 9, '2026-10-01 08:49:46.977+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d55eaad4-9cd2-4fe1-88b8-1e88b1334b81', '30494876-3b49-4ac7-9ce7-2899bb300664', NULL, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'Check who pays for water, electricity and internet, and how the deposit is returned. Get it written in the contract.', 3, '2026-10-01 11:49:46.978+08', NULL);
