INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('0ca79848-f44d-407a-a60b-94b59f8843f4', 'd9e0e517-9ba9-4459-8d62-2730c3997d83', NULL, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'Does anyone here play rugby or ultimate? Those are the ones I can never find numbers for.', 7, '2026-09-30 18:49:46.986+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('c19be997-6377-45ef-9b94-6faf312c3245', 'd9e0e517-9ba9-4459-8d62-2730c3997d83', '0ca79848-f44d-407a-a60b-94b59f8843f4', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Start a thread for it on this board — I know at least three people who would turn up.', 5, '2026-09-30 19:49:46.987+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('97b24569-6e39-4066-8598-b017e672ab46', '42580320-8118-4e98-8f3d-ceeef805e0de', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', '其实大部分社团都欢迎留学生，只是很少有人主动来问。建议直接去活动现场看看，比在群里发消息有用得多。', 19, '2026-09-30 02:49:46.987+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('2c5d1825-e4c2-4031-bf89-983acbac1fa7', '42580320-8118-4e98-8f3d-ceeef805e0de', '97b24569-6e39-4066-8598-b017e672ab46', '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'That is encouraging, thank you. I think I was overthinking it.', 7, '2026-09-30 04:49:46.987+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('fb3bb807-4836-4328-b173-3e5971db3d3b', '42580320-8118-4e98-8f3d-ceeef805e0de', NULL, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Photography, badminton and the volunteer societies all had someone who switched to English the moment I turned up. The academic ones were harder going.', 14, '2026-09-30 05:49:46.988+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('045ba98f-3f1d-49b7-aacb-0c7cee1d9772', '42580320-8118-4e98-8f3d-ceeef805e0de', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'The club fair at the start of each semester is the easy way in: everyone is recruiting at once, and nobody minds you asking basic questions.', 9, '2026-09-30 10:49:46.988+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d70ad8ed-a0a7-4c6d-a8db-0e26d0375c06', 'ac666426-ff67-4939-a9e8-f46f783e6f7e', NULL, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'Coming. Do people shoot film too, or digital only?', 8, '2026-10-01 07:49:46.988+08', NULL);
