INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d962c090-363e-4285-873c-44a388339227', '707d30f9-9afc-4283-aa0b-2cbde025a11d', NULL, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Nine desserts sounds fine to me, honestly.', 5, '2026-09-30 10:49:46.991+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('10045754-47bf-4a29-988b-bfb7a1671ccb', 'bb09df51-03ae-4123-828b-82232498262a', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'Please do not rely on a forum for this one — ask the International Student Office directly. The rules depend on your visa type and whether the university approves it, and getting it wrong can affect your permit.', 21, '2026-09-28 20:49:46.991+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('e7207786-01c3-4339-ac19-14d8fa7c97b4', 'bb09df51-03ae-4123-828b-82232498262a', '10045754-47bf-4a29-988b-bfb7a1671ccb', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Fair. I will book a meeting with them.', 7, '2026-09-28 22:49:46.991+08', NULL);
