INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('09e6fc48-0946-463e-8c7f-776f8d40ac46', 'f1d4be20-3475-4dbc-82c1-c8b6f5fb95cb', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Also: a small power strip with a switch. Plugs are never where you want them.', 6, '2026-09-30 17:49:46.992+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('17a7f58b-fa43-4501-8111-6bf017d0c930', 'a69a555d-a011-412f-8e2d-df0b785e1894', NULL, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', '我去年选过，平时作业占比比较高，期末是开卷。英文阅读量不小。', 7, '2026-09-29 13:49:46.993+08', NULL);
