INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('e4239115-53a6-4ee8-a4e3-ae7c4b1d8b49', '85418831-7ca8-4f43-88dd-80f7df8f429b', NULL, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'The phone number part is key. They would not open it without one.', 19, '2026-09-26 20:49:46.994+08', NULL);
